#!/usr/bin/env python3\n\n\"\"\"\nIP Geolocation Lookup\n\nهذه الأداة تستقبل عنوان IP من سطر الأوامر أو من stdin وتستعلم عن موقعه الجغرافي عبر خدمة ip-api.com.\nتُعيد النتيجة كـ JSON على stdout.\n\"\"\"\nimport sys, json, requests\n\n\ndef main():\n    # قراءة عنوان IP من argv أو stdin\n    if len(sys.argv) > 1:\n        ip = sys.argv[1].strip()\n    else:\n        ip = sys.stdin.read().strip()\n\n    if not ip:\n        print(json.dumps({"error": "No IP provided"}, ensure_ascii=False))\n        return\n\n    try:\n        # طلب إلى ip-api.com (بدون تحقق SSL لتقليل المتطلبات)\n        resp = requests.get(f\"http://ip-api.com/json/{ip}\", timeout=10, verify=False)\n        data = resp.json()\n    except Exception as e:\n        print(json.dumps({"error": str(e)}, ensure_ascii=False))\n        return\n\n    # طباعة النتيجة بصيغة JSON\n    print(json.dumps(data, ensure_ascii=False))\n\n\nif __name__ == "__main__":\n    main()